-- menu-prices.sql — server-side source of truth for charging.
-- GENERATED by `npm run menu:sql` from src/data/menu.ts — do not hand-edit.
-- The Netlify create-payment-intent function totals an order from THESE prices
-- (never the amount the client sends), so a tampered client can't underpay.
--
-- Run in Supabase: SQL Editor ▸ New query ▸ paste ▸ Run — BEFORE deploying the
-- app, or new items fail at checkout with "Unknown item". Safe to re-run.
-- Prices are in CENTS.

create table if not exists public.menu_prices (
  item_id    text primary key,
  base_cents int  not null,
  -- option name → price delta in cents, e.g. {"Double": 300}
  options    jsonb not null default '{}',
  -- addon name → price delta in cents, e.g. {"Bacon": 200}
  addons     jsonb not null default '{}'
);

alter table public.menu_prices enable row level security;
drop policy if exists "anyone can read prices" on public.menu_prices;
create policy "anyone can read prices" on public.menu_prices for select using (true);

begin;

-- drop items that are no longer on the menu
delete from public.menu_prices where item_id not in ('specialty-burger', 'lobster-rangoon', 'stuffies', 'cheeseburger', 'hamburger', 'hot-dog', 'hot-wieners', 'sausage-peppers-onions', 'chicken-tenders', 'chicken-wings', 'buffalo-chicken-balls', 'beef-empanadas', 'mac-cheese-bites', 'fried-ravioli', 'rice-balls', 'jalapeno-poppers', 'mozzarella-sticks', 'broccoli-cheese-bites', 'zucchini-sticks', 'fries', 'potato-tots', 'onion-rings', 'doughboy', 'ice-cream', 'chips', 'drink');

insert into public.menu_prices (item_id, base_cents, options, addons) values
  ('specialty-burger', 1100, '{}', '{}'),  -- Pam's Specialty Burger $11.00
  ('lobster-rangoon', 1500, '{}', '{}'),  -- Lobster Rangoon $15.00
  ('stuffies', 600, '{}', '{}'),  -- Homemade Stuffies $6.00
  ('cheeseburger', 800, '{}', '{}'),  -- Cheeseburger $8.00
  ('hamburger', 700, '{}', '{}'),  -- Hamburger $7.00
  ('hot-dog', 600, '{}', '{}'),  -- Hot Dog $6.00
  ('hot-wieners', 500, '{}', '{}'),  -- Hot Wieners $5.00
  ('sausage-peppers-onions', 1500, '{}', '{}'),  -- Sausage, Peppers & Onions $15.00
  ('chicken-tenders', 900, '{}', '{}'),  -- Chicken Tenders $9.00
  ('chicken-wings', 1000, '{}', '{}'),  -- Chicken Wings $10.00
  ('buffalo-chicken-balls', 1500, '{}', '{}'),  -- Buffalo Chicken Balls $15.00
  ('beef-empanadas', 1200, '{}', '{}'),  -- Beef Empanadas $12.00
  ('mac-cheese-bites', 1000, '{}', '{}'),  -- Mac & Cheese Bites $10.00
  ('fried-ravioli', 1300, '{}', '{}'),  -- Fried Ravioli $13.00
  ('rice-balls', 1200, '{}', '{}'),  -- Rice Balls $12.00
  ('jalapeno-poppers', 900, '{}', '{}'),  -- Jalapeño Poppers $9.00
  ('mozzarella-sticks', 1000, '{}', '{}'),  -- Mozzarella Sticks $10.00
  ('broccoli-cheese-bites', 900, '{}', '{}'),  -- Broccoli & Cheese Bites $9.00
  ('zucchini-sticks', 900, '{}', '{}'),  -- Zucchini Sticks $9.00
  ('fries', 600, '{}', '{}'),  -- Fries $6.00
  ('potato-tots', 900, '{}', '{}'),  -- Potato Tots $9.00
  ('onion-rings', 900, '{}', '{}'),  -- Onion Rings $9.00
  ('doughboy', 1000, '{}', '{}'),  -- Large Doughboy $10.00
  ('ice-cream', 500, '{}', '{}'),  -- Novelty Ice Cream $5.00
  ('chips', 200, '{}', '{}'),  -- Chips $2.00
  ('drink', 300, '{"Coke":0,"Diet Coke":0,"Sprite":0,"Water":0,"Gatorade":0}', '{}')  -- Drink $3.00
on conflict (item_id) do update
  set base_cents = excluded.base_cents,
      options    = excluded.options,
      addons     = excluded.addons;

commit;

-- Stripe PaymentIntent id, stored on the order once payment succeeds.
alter table public.orders add column if not exists payment_ref text;
grant select (payment_ref) on public.orders to anon, authenticated;
